css:
:root { --paper: #E7E6E1; --paper-panel: #DBDAD2; --paper-panel-2: #D1CFC5; --ink-soft: #6B6960; --line: #C7C5BB; --mono: ui-monospace, 'SF Mono', 'Cascadia Mono', Consolas, 'Roboto Mono', monospace; }

body { background: var(--paper); }

/* Header — wordmark + nav in mono, hairline rule instead of a shadowed bar */
[data-theme-section="header"] { background: var(--paper); border-bottom: 1px solid var(--line); box-shadow: none; }
[data-theme-section="header"] .theme-header-logo { font-family: var(--mono); font-weight: 600; letter-spacing: 0.18em; color: var(--primary); }
[data-theme-section="header"] .theme-header-logo::after { content: ""; display: inline-block; width: 6px; height: 6px; background: var(--accent); border-radius: 50%; margin-left: 6px; vertical-align: middle; }
[data-theme-section="announcement-bar"] { background: var(--paper); color: var(--ink-soft); border-bottom: 1px solid var(--line); font-family: var(--mono); font-size: 0.7rem; letter-spacing: 0.04em; }
[data-theme-section="header"] .theme-header-nav a { font-family: var(--mono); font-size: 0.8rem; letter-spacing: 0.02em; color: var(--primary); }
[data-theme-section="header"] .theme-header-nav a:hover { color: var(--accent); }
[data-theme-section="header"] .theme-header-actions { font-family: var(--mono); font-size: 0.78rem; color: var(--ink-soft); }
[data-theme-section="header"] .theme-header-cart-badge { background: var(--accent); border-radius: 2px; }

/* Hero — flat panel, no gradient banner; showcase area reads like a device bezel */
[data-theme-section="hero"] { border-bottom: 1px solid var(--line); }
[data-theme-section="hero"] .theme-hero-title { font-weight: 600; letter-spacing: -0.01em; }
[data-theme-section="hero"] .theme-hero-cta { background: var(--primary); color: var(--primary-text); font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.06em; text-transform: uppercase; border-radius: var(--radius-btn); }
[data-theme-section="hero"] .theme-hero-cta:hover { background: var(--primary-hover); }
[data-theme-section="hero"][data-variant="showcase"] .theme-hero-showcase { background: none; }
[data-theme-section="hero"][data-variant="showcase"] .theme-device { width: min(100%, 360px); aspect-ratio: 4/5; background: linear-gradient(155deg, var(--paper-panel-2), var(--paper-panel)); border-radius: 6px; padding: 16px; box-shadow: 0 30px 60px -30px rgba(0,0,0,0.35); }
[data-theme-section="hero"][data-variant="showcase"] .theme-device-screen { height: 100%; width: 100%; background: var(--paper); border: 1px solid var(--line); display: flex; flex-direction: column; justify-content: space-between; padding: 20px; position: relative; overflow: hidden; }
[data-theme-section="hero"][data-variant="showcase"] .theme-device-screen::before { content: ""; position: absolute; inset: 0; background-image: repeating-linear-gradient(0deg, rgba(0,0,0,0.025) 0px, rgba(0,0,0,0.025) 1px, transparent 1px, transparent 3px); pointer-events: none; }
[data-theme-section="hero"][data-variant="showcase"] .theme-device-month { font-family: var(--mono); font-size: 0.7rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-soft); }
[data-theme-section="hero"][data-variant="showcase"] .theme-device-date { font-family: var(--mono); font-size: 4.6rem; line-height: 1; font-weight: 600; color: var(--primary); align-self: center; }
[data-theme-section="hero"][data-variant="showcase"] .theme-device-caption { font-size: 0.78rem; color: var(--ink-soft); display: flex; justify-content: space-between; font-family: var(--mono); }
[data-theme-section="hero"][data-variant="showcase"] .theme-device-refresh { animation: still-refresh 1.4s ease-out 1; }
@keyframes still-refresh { 0% { filter: invert(0); } 8% { filter: invert(1); } 16% { filter: invert(0); } 24% { filter: invert(1); } 34% { filter: invert(0); } 100% { filter: invert(0); } }
@media (prefers-reduced-motion: reduce) { [data-theme-section="hero"][data-variant="showcase"] .theme-device-refresh { animation: none; } }

/* Brand statement — quiet, centered, mono eyebrow */
[data-theme-section="home-brand"] { background: var(--paper); border-bottom: 1px solid var(--line); text-align: center; padding: 4rem 1rem; }
[data-theme-section="home-brand"] p { font-size: clamp(1.15rem, 2vw, 1.5rem); font-weight: 500; line-height: 1.45; max-width: 42rem; margin: 0 auto; color: var(--primary); }

/* Trust badges repurposed as a spec strip — hairline-divided key/value row instead of icon cards */
[data-theme-section="home-trust"][data-variant="spec-strip"] { background: var(--paper); border-bottom: 1px solid var(--line); }
[data-theme-section="home-trust"] .theme-spec-strip-grid { max-width: 1180px; margin: 0 auto; padding: 22px clamp(20px, 4vw, 48px); display: grid; grid-template-columns: repeat(4, 1fr); }
[data-theme-section="home-trust"] .theme-spec { padding: 0 22px; border-left: 1px solid var(--line); }
[data-theme-section="home-trust"] .theme-spec:first-child { border-left: none; padding-left: 0; }
[data-theme-section="home-trust"] .theme-spec-k { font-family: var(--mono); font-size: 0.66rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-soft); display: block; margin-bottom: 6px; }
[data-theme-section="home-trust"] .theme-spec-v { font-family: var(--mono); font-size: 1.05rem; display: block; color: var(--primary); }
@media (max-width: 760px) { [data-theme-section="home-trust"] .theme-spec-strip-grid { grid-template-columns: 1fr 1fr; row-gap: 18px; } [data-theme-section="home-trust"] .theme-spec:nth-child(3) { border-left: none; padding-left: 0; } }

/* Product cards — hairline-divided "plates" grid with a device-style thumbnail, mono price, spec chips */
[data-theme-section="product-grid"][data-variant="grid-2"] { gap: 1px; background: var(--line); border: 1px solid var(--line); }
[data-theme-section="product-card"] .theme-card-image { border-radius: var(--radius-card); background: var(--paper-panel); box-shadow: none; }
[data-theme-section="product-card"] .theme-card-title { font-weight: 500; color: var(--primary); }
[data-theme-section="product-card"]:hover .theme-card-title { color: var(--accent); }
[data-theme-section="product-card"] .theme-card-price { font-family: var(--mono); }
[data-theme-section="product-card"][data-variant="plate"] { background: var(--paper); padding: clamp(20px, 3vw, 32px); display: flex; flex-direction: column; gap: 16px; transition: background 0.2s ease; }
[data-theme-section="product-card"][data-variant="plate"]:hover { background: var(--paper-panel); }
[data-theme-section="product-card"][data-variant="plate"] .theme-plate-screen { aspect-ratio: 16/10; background: var(--paper-panel-2); border-radius: 4px; padding: 12px; }
[data-theme-section="product-card"][data-variant="plate"] .theme-plate-screen img { width: 100%; height: 100%; object-fit: cover; border-radius: 2px; }
[data-theme-section="product-card"][data-variant="plate"] .theme-plate-mountains { width: 46%; opacity: 0.5; fill: var(--ink-soft); }
[data-theme-section="product-card"][data-variant="plate"] .theme-card-title { font-size: 1.1rem; font-weight: 600; margin: 0 0 6px; }
[data-theme-section="product-card"][data-variant="plate"] .theme-plate-desc { font-size: 0.85rem; color: var(--ink-soft); line-height: 1.5; max-width: 34ch; margin: 0; }
[data-theme-section="product-card"][data-variant="plate"] .theme-card-price { font-family: var(--mono); font-size: 1rem; }
[data-theme-section="product-card"][data-variant="plate"] .theme-chip { font-family: var(--mono); font-size: 0.64rem; letter-spacing: 0.05em; text-transform: uppercase; border: 1px solid var(--line); padding: 3px 7px; border-radius: 2px; color: var(--ink-soft); }
@media (max-width: 760px) { [data-theme-section="product-grid"][data-variant="grid-2"] { grid-template-columns: 1fr !important; } }

/* Footer — minimal, same paper ground, no dark block */
[data-theme-section="footer"] { background: var(--paper); border-top: 1px solid var(--line); }
[data-theme-section="footer"] .theme-footer-copyright, [data-theme-section="footer"] a { font-family: var(--mono); font-size: 0.75rem; }
[data-theme-section="footer"] a:hover { color: var(--accent); }
[data-theme-section="footer"] .theme-footer-wordmark { font-family: var(--mono); letter-spacing: 0.18em; font-size: 0.85rem; color: var(--primary); }

/* Hero eyebrow + accent phrase + secondary ghost CTA */
[data-theme-section="hero"] .theme-hero-eyebrow { font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ink-soft); margin-bottom: 10px; }
[data-theme-section="hero"] .theme-hero-em { font-style: normal; color: var(--accent); }
[data-theme-section="hero"] .theme-hero-cta-secondary { font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--primary); background: none; border: 1px solid var(--line); border-radius: var(--radius-btn); }
[data-theme-section="hero"] .theme-hero-cta-secondary:hover { border-color: var(--primary); }

/* Shared mono eyebrow label — used above the featured-products heading and the brand statement */
.theme-eyebrow { font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ink-soft); }
[data-theme-section="home-featured"] .theme-featured-heading { font-weight: 600; }

/* Utility bar — static ships-worldwide line + live clock, no scrolling marquee */
[data-theme-section="announcement-bar"][data-variant="utility"] .theme-utility-bar-row { height: 34px; }
[data-theme-section="announcement-bar"][data-variant="utility"] .theme-utility-clock { font-variant-numeric: tabular-nums; }

/* Plate placeholder illustration — white "screen" inset inside the colored bezel */
[data-theme-section="product-card"][data-variant="plate"] .theme-plate-inner-screen { height: 100%; width: 100%; background: var(--paper); border: 1px solid var(--line); }
